#include "networks_document.hpp"
#include <charconv>
#include <cmath>
#include <sstream>
#include <stdexcept>
namespace tora::desktop {
namespace {
void text(const std::string& s){if(s.find_first_of("\r\n\0",0,3)!=std::string::npos)throw std::invalid_argument("Network text must occupy one line.");}
std::optional<double> number(std::string_view s){while(!s.empty()&&(s.front()==' '||s.front()=='\t'))s.remove_prefix(1);while(!s.empty()&&(s.back()==' '||s.back()=='\t'))s.remove_suffix(1);if(s=="infinity"||s.empty())return {};if(s.front()=='+')s.remove_prefix(1);double v=0;const auto p=std::from_chars(s.data(),s.data()+s.size(),v);if(s.empty()||p.ec!=std::errc{}||p.ptr!=s.data()+s.size()||!std::isfinite(v))throw std::invalid_argument("Enter a finite edge value or infinity for an absent edge.");return v;}
std::string line(std::istream& in){std::string s;if(!std::getline(in,s))throw std::invalid_argument("Truncated Network file.");if(!s.empty()&&s.back()=='\r')s.pop_back();return s;}
int integer(std::istream& in){auto s=line(in);int v=0;auto p=std::from_chars(s.data(),s.data()+s.size(),v);if(p.ec!=std::errc{}||p.ptr!=s.data()+s.size())throw std::invalid_argument("Invalid Network integer.");return v;}
std::string quoted(std::istream& in){auto s=line(in);if(s.size()<2||s.front()!='"'||s.back()!='"')throw std::invalid_argument("Expected a quoted Network field.");std::string out;for(std::size_t i=1;i+1<s.size();++i){if(s[i]=='"'){if(i+2>=s.size()||s[i+1]!='"')throw std::invalid_argument("Invalid embedded Network quote.");++i;}out+=s[i];}text(out);return out;}
std::string quote(const std::string& s){std::string out="\"";for(char c:s){out+=c;if(c=='"')out+=c;}return out+'"';}
int marker(NetworkMode mode){return mode==NetworkMode::MinimalTree?7001:mode==NetworkMode::ShortestRoute?0:7004;}
}
NetworksDocument NetworksDocument::blank(NetworkMode mode,int nodes,std::string title,core::NumberFormat f){if(nodes<1||nodes>100)throw std::invalid_argument("Networks require 1 to 100 nodes.");text(title);(void)core::NumberFormatter(f);NetworksDocument d;d.nodes_=nodes;d.mode_=mode;d.title_=std::move(title);d.format_=f;d.symmetrical_=mode==NetworkMode::MinimalTree;d.cells_.resize(static_cast<std::size_t>((nodes+1)*(nodes+1)));d.cells_[0]="Node Name";for(int r=1;r<=nodes;++r)for(int c=1;c<=nodes;++c)if(r!=c)d.cells_[d.index(r,c)]=mode==NetworkMode::MaximalFlow?core::NumberFormatter(f).format(0):"infinity";return d;}
std::size_t NetworksDocument::index(int r,int c)const{if(r<0||c<0||r>nodes_||c>nodes_)throw std::out_of_range("Network grid position is outside the matrix.");return static_cast<std::size_t>(r*(nodes_+1)+c);}
const std::string& NetworksDocument::cell(int r,int c)const{return cells_.at(index(r,c));}
NetworksDocument NetworksDocument::decode(std::string_view bytes,NetworkMode expected){if(bytes.size()>4*1024*1024)throw std::invalid_argument("Network file exceeds the 4 MiB limit.");std::istringstream in{std::string(bytes)};if(integer(in)!=marker(expected))throw std::invalid_argument("The file does not match the selected Network model. A marker-0 file requires explicit Shortest Route selection.");core::NumberFormat f;f.n=integer(in);f.d=integer(in);const auto notation=integer(in);if(notation!=1&&notation!=2)throw std::invalid_argument("Invalid Network notation.");f.notation=notation==1?core::Notation::Decimal:core::Notation::Scientific;auto title=quoted(in);const auto count=integer(in);auto d=blank(expected,count,title,f);for(int r=0;r<=count;++r)for(int c=0;c<=count;++c){auto s=quoted(in);if(r&&c&&r!=c){auto v=number(s);if(expected==NetworkMode::MaximalFlow&&v&&*v<0)throw std::invalid_argument("Flow capacities must be nonnegative.");}d.cells_[d.index(r,c)]=std::move(s);}const auto symmetry=integer(in);if(symmetry!=0&&symmetry!=1)throw std::invalid_argument("Invalid Network symmetry flag.");d.symmetrical_=symmetry==1;if(in.peek()!=std::char_traits<char>::eof())throw std::invalid_argument("Unexpected Network records.");d.original_=std::string(bytes);return d;}
std::string NetworksDocument::encode()const{if(!original_.empty())return original_;std::ostringstream out;out<<marker(mode_)<<"\r\n"<<format_.n<<"\r\n"<<format_.d<<"\r\n"<<(format_.notation==core::Notation::Decimal?1:2)<<"\r\n"<<quote(title_)<<"\r\n"<<nodes_<<"\r\n";for(const auto& s:cells_)out<<quote(s)<<"\r\n";out<<(symmetrical_?1:0)<<"\r\n";return out.str();}
void NetworksDocument::setCell(int r,int c,std::string s){const auto at=index(r,c);if(cells_[at]==s)return;text(s);if(r==0&&c==0)throw std::invalid_argument("The Node Name heading is fixed.");if(r&&c){if(r==c)throw std::invalid_argument("Network diagonal cells are reserved.");auto v=number(s);if(mode_==NetworkMode::MaximalFlow&&v&&*v<0)throw std::invalid_argument("Flow capacities must be nonnegative.");}cells_[at]=std::move(s);if(r==0||c==0||symmetrical_)cells_[index(c,r)]=cells_[at];original_.clear();}
void NetworksDocument::setTitle(std::string s){text(s);if(title_!=s){title_=std::move(s);original_.clear();}}
void NetworksDocument::setFormat(core::NumberFormat f){(void)core::NumberFormatter(f);format_=f;original_.clear();}
void NetworksDocument::setSymmetrical(bool value){if(symmetrical_==value)return;symmetrical_=value;if(value)for(int r=1;r<=nodes_;++r)for(int c=r+1;c<=nodes_;++c)cells_[index(c,r)]=cells_[index(r,c)];original_.clear();}
void NetworksDocument::insertNode(int position){if(position<0||position>nodes_)throw std::invalid_argument("Invalid node insertion position.");auto next=blank(mode_,nodes_+1,title_,format_);next.symmetrical_=symmetrical_;for(int r=0;r<=nodes_;++r)for(int c=0;c<=nodes_;++c)next.cells_[next.index(r+(r>position?1:0),c+(c>position?1:0))]=cell(r,c);*this=std::move(next);}
void NetworksDocument::eraseNode(int position){if(position<0||position>=nodes_||nodes_<=1)throw std::invalid_argument("Keep at least one node.");auto next=blank(mode_,nodes_-1,title_,format_);next.symmetrical_=symmetrical_;const int deleted=position+1;for(int r=0;r<=nodes_;++r)for(int c=0;c<=nodes_;++c)if(r!=deleted&&c!=deleted)next.cells_[next.index(r-(r>deleted?1:0),c-(c>deleted?1:0))]=cell(r,c);*this=std::move(next);}
networks::Graph NetworksDocument::graph()const{networks::Graph g;g.nodeCount=static_cast<std::size_t>(nodes_);g.directed=mode_==NetworkMode::MaximalFlow||(mode_==NetworkMode::ShortestRoute&&!symmetrical_);for(int r=1;r<=nodes_;++r)for(int c=1;c<=nodes_;++c){if(r==c||(!g.directed&&r>c))continue;auto value=number(cell(r,c));if(!g.directed&&value!=number(cell(c,r)))throw std::invalid_argument("An undirected network requires matching costs in both directions.");if(value)g.edges.push_back({static_cast<std::size_t>(r-1),static_cast<std::size_t>(c-1),*value});}return g;}
std::string NetworksDocument::nodeName(int position)const{if(position<0||position>=nodes_)throw std::out_of_range("Invalid node.");const auto& s=cell(0,position+1);return s.empty()?std::to_string(position+1):s;}
}
